"""
Runs the common benchmarks with one compiler, several times each, and saves the numbers for the Performance History wiki page.

    python3 benchmarks/history.py --blitzcc PATH --label NAME [--runs 3] [--only compile,emitted,...] [--wine] [--out FILE]

Every benchmark is run --runs times (3). The number that is kept is the mean of the runs, with the standard deviation next to it; all
runs are kept in the JSON file as well, so rows can be compared (benchmarks/history_page.py calls a change real when it is over two standard deviations of the difference
between neighbouring rows). NAME.json in the checkout of the performance-history branch (PERF_HISTORY, default ../performance-history next to the repository) is the default output.

The benchmarks are the ones in this folder, compiled with the compiler that is given, so the compiler of a commit or the original
Blitz3D (--wine runs the original Blitz3D 1.118 under Wine, tools/original_blitz3d.sh setup installs it):

    compile    time and size of compiling a small, a 3D and a big program         (Compiling)
    emitted    benchmarks/emitted.bb: loops, math, arrays, types, strings, calls  (Emitted Code)
    movies     benchmarks/movies.bb: CPU time of playing a movie                  (Movies)
    audio      benchmarks/audio.bb: load time and CPU time of mixing              (Audio)
    flythrough benchmarks/flythrough.bb, waterfall.bb, dungeon.bb, loading.bb      (Scene)
    lights     benchmarks/many_lights.bb: 8, 32 and 127 lights                    (Scene)
    gpu        GPU time of the passes of the waterfall, from BLITZ_FPS            (GPU)
    stranded2  tests/stranded2 with tools/benchmark_stranded2.py                   (Real Application Performance)

Without a display the programs run under xvfb-run, which with Mesa means llvmpipe, a software rasterizer: the milliseconds are then
mostly the CPU drawing pixels. With --wine the original runs under Wine on top of that, which is only there to have a number to put next
to the others, it is not what the original does on a real computer. A benchmark that a compiler can't build or run is stored as
{"error": "..."} and shown as "n/a".
"""
import argparse
import datetime
import json
import os
import platform
import re
import resource
import shutil
import statistics
import struct
import subprocess
import sys
import tempfile
import time
import zlib

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
RESULTS = os.environ.get("PERF_HISTORY", os.path.join(os.path.dirname(ROOT), "performance-history"))  # a checkout of the performance-history branch
WINE_HOME = os.environ.get("B3D_ORIG_HOME", "/opt/b3d")
QUICK = False  # --quick: the short set for every commit (no Stranded II compile, a smaller emitted-code run)

# The size of every window and the amount of work of the scene benchmarks: small enough to run ten times a commit on llvmpipe.
SCENES = {
    "flythrough": {"env": {"BENCH_OBJECTS": "5000", "BENCH_FRAMES": "100", "BENCH_W": "320", "BENCH_H": "180"},
                   "keys": ["ms_avg", "tris", "draws"]},
    "waterfall": {"env": {"BENCH_SPRITES": "2000", "BENCH_FRAMES": "100", "BENCH_W": "320", "BENCH_H": "180"},
                  "keys": ["ms_avg", "update_ms", "draws"]},
    "dungeon": {"env": {"BENCH_FRAMES": "100", "BENCH_W": "320", "BENCH_H": "180"},
                "keys": ["ms_avg", "update_ms", "draws"]},
}


def quantile(sorted_values, q):
    """Linear interpolation between the closest ranks."""
    if len(sorted_values) == 1:
        return sorted_values[0]
    position = (len(sorted_values) - 1) * q
    low = int(position)
    high = min(low + 1, len(sorted_values) - 1)
    return sorted_values[low] + (sorted_values[high] - sorted_values[low]) * (position - low)


def summarize(runs):
    """runs: list of {key: number}. Gives {key: {"value": mean, "stdev": , "runs": [...], "min": , "max": }}"""
    out = {}
    for key in runs[0]:
        series = [r[key] for r in runs if key in r]
        ordered = sorted(series)
        out[key] = {"value": statistics.fmean(series), "stdev": statistics.stdev(series) if len(series) > 1 else 0.0,
                    "runs": series, "min": ordered[0], "max": ordered[-1], "n": len(series)}
    return out


class Compiler:
    def __init__(self, path, wine):
        self.path = path
        self.wine = wine
        self.display = [] if os.environ.get("DISPLAY") else ["xvfb-run", "-a", "-s", "-screen 0 1024x768x24"]
        if wine:
            self.env = dict(os.environ, WINEARCH="win32", WINEPREFIX=os.environ.get("WINEPREFIX", "/opt/wine32"), WINEDEBUG="-all",
                            BLITZPATH="Z:" + WINE_HOME.replace("/", "\\"))
            self.path = os.path.join(WINE_HOME, "bin", "blitzcc.exe")
            self.llvm = False
            self.version = "Blitz3D 1.118 (original) under Wine"
        else:
            self.env = dict(os.environ, XDG_RUNTIME_DIR=os.environ.get("XDG_RUNTIME_DIR", "/tmp/xdg-runtime"))
            os.makedirs(self.env["XDG_RUNTIME_DIR"], mode=0o700, exist_ok=True)
            self.version = " ".join(subprocess.run([path, "-v"], capture_output=True, text=True).stdout.split())
            self.llvm = bool(re.search(r"Compiler version:20\d\d\.", self.version))

    def compile_cmd(self, source, output, extra=()):
        cmd = [self.path, "-q"] + list(extra) + ["-o", output, source]
        return (["wine"] + cmd) if self.wine else cmd

    def program_path(self, directory, name):
        return os.path.join(directory, name + (".exe" if self.wine else ""))

    def run_cmd(self, program):
        return self.display + ((["wine", program]) if self.wine else [program])

    def native_path(self, path):
        """The path as the program sees it: Wine programs see Z:\\ paths."""
        return ("Z:" + path.replace("/", "\\")) if self.wine else path


def build(compiler, directory, name, counters=None, extra=(), source=None):
    """Builds benchmarks/<name>.bb (with the include of the compiler next to it). Falls back to the original's include (MilliSecs only)
    when this compiler can't build the BlitzLLVM one, which is the case for the first commits (no Microseconds, no Stats3D)."""
    src = os.path.join(directory, name + ".bb")
    shutil.copy(source or os.path.join(HERE, name + ".bb"), src)
    program = compiler.program_path(directory, name)
    tried = []
    for variant in (["llvm", "original"] if compiler.llvm else ["original"]):
        if counters:
            shutil.copy(os.path.join(HERE, "%s_%s.bi" % (counters, variant)), os.path.join(directory, counters + "_counters.bi"))
        r = subprocess.run(compiler.compile_cmd(src, program, extra), cwd=directory, capture_output=True, text=True, env=compiler.env)
        if r.returncode == 0 and os.path.isfile(program):
            return program, variant
        tried.append(variant + ": " + (r.stdout + r.stderr).strip()[-300:])
        if not counters:
            break
    raise RuntimeError("build failed: " + " | ".join(tried))


def parse_result(path):
    text = open(path).read()
    line = next(l for l in text.splitlines() if "RESULT " in l)
    return {k: float(v) for k, v in re.findall(r"(\w+)=([-+\d.eE]+)", line.split("RESULT ", 1)[1])}


def run_program(compiler, program, env, cwd, timeout=900, args=()):
    """Runs a program; gives (rusage CPU seconds of it, wall seconds, output)."""
    full = dict(compiler.env, **env)
    before = resource.getrusage(resource.RUSAGE_CHILDREN)
    t0 = time.time()
    r = subprocess.run(compiler.run_cmd(program) + list(args), cwd=cwd, env=full, capture_output=True, text=True, timeout=timeout)
    wall = time.time() - t0
    after = resource.getrusage(resource.RUSAGE_CHILDREN)
    cpu = (after.ru_utime - before.ru_utime) + (after.ru_stime - before.ru_stime)
    return cpu, wall, r.stdout + r.stderr, r.returncode


def bench_scene(compiler, name, runs):
    cfg = SCENES[name]
    with tempfile.TemporaryDirectory() as d:
        program, variant = build(compiler, d, name, counters=name)
        results = []
        for i in range(runs):
            result_file = os.path.join(d, "result.txt")
            if os.path.exists(result_file):
                os.remove(result_file)
            env = dict(cfg["env"], BENCH_RESULT=compiler.native_path(result_file), BENCH_SEED="1")
            if os.path.isfile(os.path.join(ROOT, "tests", "suite", "models", "textured.3ds")):
                env["BENCH_MODEL"] = compiler.native_path(os.path.join(ROOT, "tests", "suite", "models", "textured.3ds"))
            cpu, wall, out, code = run_program(compiler, program, env, d)
            if not os.path.isfile(result_file):
                raise RuntimeError("no result (exit %s): %s" % (code, out[-300:]))
            r = parse_result(result_file)
            results.append({k: r[k] for k in cfg["keys"] if k in r})
        summary = summarize(results)
        summary["_timer"] = "microseconds" if variant == "llvm" else "milliseconds"
        return summary


def make_png(path, size, seed):
    state = seed * 2654435761 % 2**32 or 1
    rows = bytearray()
    for _ in range(size):
        rows.append(0)
        line = bytearray(size * 3)
        for i in range(0, size * 3, 4):
            state = (state * 1664525 + 1013904223) % 2**32
            line[i:i + 4] = state.to_bytes(4, "little")[:len(line[i:i + 4])]
        rows += line
    def chunk(tag, data):
        body = tag + data
        return struct.pack(">I", len(data)) + body + struct.pack(">I", zlib.crc32(body) & 0xFFFFFFFF)
    with open(path, "wb") as f:
        f.write(b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", size, size, 8, 2, 0, 0, 0)) + chunk(b"IDAT", zlib.compress(bytes(rows), 1)) + chunk(b"IEND", b""))


def bench_loading(compiler, runs):
    with tempfile.TemporaryDirectory() as d:
        count = 32
        for i in range(count):
            make_png(os.path.join(d, "tex%d.png" % i), 256, i + 1)
        program, variant = build(compiler, d, "loading", counters="loading")
        modes = ["blocking"] + (["async"] if compiler.llvm else [])
        out = {}
        for mode in modes:
            results = []
            for i in range(runs + 1):
                result_file = os.path.join(d, "result.txt")
                if os.path.exists(result_file):
                    os.remove(result_file)
                env = {"BENCH_DIR": compiler.native_path(d), "BENCH_TEXTURES": str(count), "BENCH_WORK": "0", "BENCH_FLAGS": "9",
                       "BENCH_ASYNC": "1" if mode == "async" else "0", "BENCH_RESULT": compiler.native_path(result_file)}
                run_program(compiler, program, env, d)
                if not os.path.isfile(result_file):
                    raise RuntimeError("no result in mode " + mode)
                if i == 0:
                    continue  # The first run warms the file cache.
                results.append({k: v for k, v in parse_result(result_file).items() if k in ("load_ms", "total_ms")})
            for key, summary in summarize(results).items():
                out["%s_%s" % (mode, key)] = summary
        return out


def bench_emitted(compiler, runs):
    with tempfile.TemporaryDirectory() as d:
        program, _ = build(compiler, d, "emitted")
        results = []
        for i in range(runs):
            result_file = os.path.join(d, "result.txt")
            if os.path.exists(result_file):
                os.remove(result_file)
            run_program(compiler, program, {"BENCH_SCALE": "3" if QUICK else "10", "BENCH_RESULT": compiler.native_path(result_file)}, d)
            if not os.path.isfile(result_file):
                raise RuntimeError("no result")
            r = parse_result(result_file)
            results.append({k: v for k, v in r.items() if k.endswith("_ms")})
            if i == 0:
                checksum = r.get("checksum")
        summary = summarize(results)
        summary["_checksum"] = checksum
        return summary


def bench_compile(compiler, runs):
    """Time and size of compiling: a hello world, the 3D flythrough benchmark and Stranded II (a real game of 40,000 lines)."""
    targets = {}
    with tempfile.TemporaryDirectory() as d:
        hello = os.path.join(d, "hello.bb")
        open(hello, "w").write('Print "Hello world"\n')
        shutil.copy(os.path.join(HERE, "flythrough.bb"), os.path.join(d, "flythrough.bb"))
        shutil.copy(os.path.join(HERE, "flythrough_original.bi"), os.path.join(d, "flythrough_counters.bi"))
        targets["hello"] = (hello, d)
        targets["flythrough"] = (os.path.join(d, "flythrough.bb"), d)
        if not QUICK:
            game = os.path.join(d, "stranded2")
            shutil.copytree(os.path.join(ROOT, "tests", "stranded2"), game)
            targets["stranded2"] = (os.path.join(game, "StrandedII.bb"), game)
        out = {}
        for name, (src, cwd) in targets.items():
            results = []
            for i in range(runs):
                program = compiler.program_path(d, "out_" + name)
                if os.path.exists(program):
                    os.remove(program)
                t0 = time.time()
                r = subprocess.run(compiler.compile_cmd(src, program), cwd=cwd, capture_output=True, text=True, env=compiler.env)
                elapsed = (time.time() - t0) * 1000
                if r.returncode != 0 or not os.path.isfile(program):
                    out[name] = {"error": (r.stdout + r.stderr).strip()[-300:]}
                    break
                results.append({"compile_ms": elapsed, "size_kb": os.path.getsize(program) / 1024})
            else:
                for key, summary in summarize(results).items():
                    out["%s_%s" % (name, key)] = summary
        return out


def bench_movies(compiler, runs):
    if not compiler.llvm:
        raise RuntimeError("the original plays movies with DirectShow, which does not run here")
    if not shutil.which("ffmpeg"):
        raise RuntimeError("ffmpeg is needed to make the test movie")
    with tempfile.TemporaryDirectory() as d:
        movie = os.path.join(d, "bench.mp4")
        subprocess.run(["ffmpeg", "-v", "error", "-f", "lavfi", "-i", "testsrc2=size=320x240:rate=30:duration=5", "-f", "lavfi", "-i",
                        "sine=frequency=440:duration=5", "-c:v", "libx264", "-pix_fmt", "yuv420p", "-c:a", "aac", "-shortest", movie], check=True)
        program, _ = build(compiler, d, "movies")
        results = []
        for i in range(runs):
            result_file = os.path.join(d, "result.txt")
            if os.path.exists(result_file):
                os.remove(result_file)
            cpu, wall, output, code = run_program(compiler, program, {"BENCH_MOVIE": movie, "BENCH_RESULT": result_file, "SDL_AUDIODRIVER": "dummy"}, d)
            if not os.path.isfile(result_file):
                raise RuntimeError("no result (exit %s): %s" % (code, output[-300:]))
            r = parse_result(result_file)
            results.append({"cpu_ms": cpu * 1000, "shown": r["shown"]})
        return summarize(results)


def bench_audio(compiler, runs):
    sfx = os.path.join(ROOT, "tests", "stranded2", "mods", "Stranded II", "sfx")
    files = sorted(f for f in os.listdir(sfx) if f.endswith(".wav"))[:16]
    with tempfile.TemporaryDirectory() as d:
        for f in files:
            shutil.copy(os.path.join(sfx, f), os.path.join(d, f))
        open(os.path.join(d, "index.txt"), "w").write("\r\n".join(files) + "\r\n")
        program, _ = build(compiler, d, "audio")
        results = []
        for i in range(runs):
            result_file = os.path.join(d, "result.txt")
            if os.path.exists(result_file):
                os.remove(result_file)
            env = {"BENCH_SOUNDS": compiler.native_path(d), "BENCH_RESULT": compiler.native_path(result_file), "SDL_AUDIODRIVER": "dummy"}
            cpu, wall, output, code = run_program(compiler, program, env, d)
            if not os.path.isfile(result_file):
                raise RuntimeError("no result (exit %s): %s" % (code, output[-300:]))
            r = parse_result(result_file)
            if r.get("loaded", 0) == 0:
                raise RuntimeError("no sound loaded")
            results.append({"load_ms": r["load_ms"], "cpu_ms": cpu * 1000})
        return summarize(results)


def bench_lights(compiler, runs):
    """benchmarks/many_lights.bb: what 8, 32 and 127 point lights cost (RenderWorld on the CPU, 5000 cubes). The original lights with 8."""
    with tempfile.TemporaryDirectory() as d:
        program, _ = build(compiler, d, "many_lights")
        results = []
        for i in range(runs):
            result_file = os.path.join(d, "many_lights.txt")
            if os.path.exists(result_file):
                os.remove(result_file)
            run_program(compiler, program, {}, d)
            if not os.path.isfile(result_file):
                raise RuntimeError("no result")
            r = {}
            for name, value in re.findall(r"^(.*?): ([\d.]+) ms/frame", open(result_file).read(), re.M):
                r[re.sub(r"\W+", "_", name.strip()).strip("_") + "_ms"] = float(value)
            results.append(r)
        return summarize(results)


def bench_gpu(compiler, runs):
    """GPU time of the passes of the waterfall (BlitzLLVM only: it reports them with --profile and BLITZ_FPS=1)."""
    if not compiler.llvm:
        raise RuntimeError("the original has no GPU timers")
    with tempfile.TemporaryDirectory() as d:
        program, _ = build(compiler, d, "waterfall", counters="waterfall", extra=["--profile"])
        results = []
        for i in range(runs):
            result_file = os.path.join(d, "result.txt")
            if os.path.exists(result_file):
                os.remove(result_file)
            env = dict(SCENES["waterfall"]["env"], BENCH_FRAMES="400", BENCH_RESULT=result_file, BLITZ_FPS="1")
            cpu, wall, output, code = run_program(compiler, program, env, d)
            frames_shown, sums, shown, first = 0, {"scene": 0.0, "frame": 0.0}, None, True
            for l in output.splitlines():
                m = re.match(r"fps: (\d+),", l)
                if m:
                    shown = int(m.group(1))
                    continue
                m = re.match(r"\s+gpu passes: scene ([\d.]+) ms, 2d ([\d.]+) ms, copy ([\d.]+) ms, present ([\d.]+) ms, frame ([\d.]+) ms", l)
                if m and shown:
                    if first:
                        first = False
                        continue
                    frames_shown += shown
                    sums["scene"] += float(m.group(1))
                    sums["frame"] += float(m.group(5))
            if not frames_shown:
                raise RuntimeError("this build reports no GPU time")
            results.append({"gpu_scene_ms": sums["scene"] / frames_shown, "gpu_frame_ms": sums["frame"] / frames_shown})
        return summarize(results)


def bench_stranded2(compiler, runs):
    """Stranded II: the game starts in the map Survival Guide, walks around for 300 frames at 640x480 and gives the time per frame."""
    sys.path.insert(0, os.path.join(ROOT, "tools"))
    import benchmark_stranded2
    if compiler.wine:
        # The decls of the Windows API calls the game makes (the original reads userlibs from its own folder).
        for f in os.listdir(os.path.join(ROOT, "tests", "stranded2", "userlibs")):
            shutil.copy(os.path.join(ROOT, "tests", "stranded2", "userlibs", f), os.path.join(WINE_HOME, "userlibs", f))
    with tempfile.TemporaryDirectory() as d:
        game = benchmark_stranded2.prepare(ROOT, d, original=not compiler.llvm)
        program = compiler.program_path(game, "stranded2_bench")
        r = subprocess.run(compiler.compile_cmd(os.path.join(game, "StrandedII.bb"), program), cwd=game, capture_output=True, text=True, env=compiler.env)
        if r.returncode != 0 or not os.path.isfile(program):
            raise RuntimeError("build failed: " + (r.stdout + r.stderr).strip()[-300:])
        results = []
        for i in range(runs):
            result_file = os.path.join(d, "result.txt")
            if os.path.exists(result_file):
                os.remove(result_file)
            env = {"BENCH_FRAMES": "300", "BENCH_W": "640", "BENCH_H": "480", "BENCH_MAP": "Survival Guide",
                   "BENCH_RESULT": compiler.native_path(result_file)}
            cpu, wall, output, code = run_program(compiler, program, env, game, args=["-win"])
            if not os.path.isfile(result_file):
                raise RuntimeError("no result (exit %s): %s" % (code, output.strip()[-300:]))
            v = dict(re.findall(r"(\w+)=([\d.]+)", open(result_file).read()))
            results.append({"ms_avg": float(v["ms_per_frame"]), "tris": float(v["tris"]), "draws": float(v["draws"])})
        return summarize(results)


def machine(wine=False):
    cpu = "unknown"
    try:
        for l in open("/proc/cpuinfo"):
            if l.startswith("model name"):
                cpu = l.split(":", 1)[1].strip()
                break
    except OSError:
        pass
    mem = ""
    try:
        for l in open("/proc/meminfo"):
            if l.startswith("MemTotal"):
                mem = "%.0f GB" % (int(l.split()[1]) / 1048576.0)
                break
    except OSError:
        pass
    os_name = platform.platform()
    try:
        info = dict(l.strip().split("=", 1) for l in open("/etc/os-release") if "=" in l)
        os_name = info.get("PRETTY_NAME", "").strip('"') + ", kernel " + platform.release()
    except OSError:
        pass
    return {"cpu": cpu, "threads": os.cpu_count(), "ram": mem, "os": os_name, "gpu": "none (Mesa llvmpipe, software rasterizer)", "vram": "none (system memory)",
            "renderer": ("Wine 9.0 wined3d (Direct3D 7 converted to OpenGL), Mesa llvmpipe 25.2.8" if wine else "Vulkan, Mesa llvmpipe 25.2.8 (lavapipe)")}


BENCHMARKS = {
    "compile": bench_compile,
    "emitted": bench_emitted,
    "movies": bench_movies,
    "audio": bench_audio,
    "flythrough": lambda c, n: bench_scene(c, "flythrough", n),
    "waterfall": lambda c, n: bench_scene(c, "waterfall", n),
    "dungeon": lambda c, n: bench_scene(c, "dungeon", n),
    "loading": bench_loading,
    "lights": bench_lights,
    "gpu": bench_gpu,
    "stranded2": bench_stranded2,
}


def main():
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--blitzcc")
    parser.add_argument("--wine", action="store_true", help="the original Blitz3D under Wine (tools/original_blitz3d.sh setup)")
    parser.add_argument("--label", required=True)
    parser.add_argument("--rev", default="", help="commit or pull request this compiler was built from")
    parser.add_argument("--runs", type=int, default=3)
    parser.add_argument("--only", default=",".join(BENCHMARKS))
    parser.add_argument("--quick", action="store_true", help="the short set for every commit: compile, emitted, flythrough, waterfall, dungeon")
    parser.add_argument("--out")
    args = parser.parse_args()
    if args.quick:
        global QUICK
        QUICK = True
        if args.only == ",".join(BENCHMARKS):
            args.only = "compile,emitted,flythrough,waterfall,dungeon"
    if not args.blitzcc and not args.wine:
        sys.exit("Give --blitzcc or --wine.")
    compiler = Compiler(os.path.abspath(args.blitzcc) if args.blitzcc else None, args.wine)
    out = args.out or os.path.join(RESULTS, args.label + ".json")
    os.makedirs(os.path.dirname(out), exist_ok=True)
    record = {"label": args.label, "rev": args.rev, "date": datetime.datetime.now(datetime.timezone.utc).isoformat(timespec="seconds"),
              "compiler": compiler.version, "runs": args.runs, "machine": machine(args.wine), "benchmarks": {}}
    if os.path.isfile(out):
        record["benchmarks"] = json.load(open(out)).get("benchmarks", {})
    for name in args.only.split(","):
        started = time.time()
        try:
            record["benchmarks"][name] = BENCHMARKS[name](compiler, args.runs)
            status = "ok"
        except Exception as e:  # A compiler of an old commit may not build a benchmark; that is a result as well.
            record["benchmarks"][name] = {"error": str(e)[:500]}
            status = "n/a: " + str(e)[:160].replace("\n", " ")
        print("%-12s %5.0fs %s" % (name, time.time() - started, status), flush=True)
        with open(out, "w") as f:
            json.dump(record, f, indent=1)


if __name__ == "__main__":
    main()
